'use strict';
const KEY='crna-hub-v2',OLD='crna-hub-starter-v1',tabs=['Dashboard','Shifts','Facilities','PTO','Credentials','Mileage','Import & Backup','Assistant','Account'];
const empty=()=>({shifts:[],facilities:[],pto:[],credentials:[],mileage:[],nbcrna:{status:'',number:'',periodStart:'',periodEnd:'',renewalDeadline:'',classA:'',classB:'',macEd:'',macDev:'',macEdRequired:60,macDevRequired:40,docNote:'',ceNote:'',reminders:'90,60,30,7'},aana:{status:'',number:'',expiration:'',docNote:'',ceNote:'',reminders:'90,60,30,7'},nbcrnaCE:[],aanaCE:[],licenses:[],assistantChat:[],settings:{ptoAnnual:0,ptoStarting:0,ptoHoursPerPeriod:0}});
function load(){let obj;try{obj=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(OLD)||'null')}catch{}const result=empty();if(obj&&typeof obj==='object')for(const k of Object.keys(result))if((k==='settings'||k==='nbcrna'||k==='aana')?obj[k]&&typeof obj[k]==='object':Array.isArray(obj[k]))result[k]=obj[k];return result}
let db=load(),tab='Dashboard',month=new Date(),selected=localDate(new Date()),editId=null;month.setDate(1);
const $=id=>document.getElementById(id),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c])),currency=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}),num=n=>Number(n||0),id=()=>crypto.randomUUID(),fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
function localDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){alert('Storage failed. Export a backup: '+e.message)}}
function setTab(t){tab=t;editId=null;render();window.scrollTo(0,0)}
function moveMonth(n){month=new Date(month.getFullYear(),month.getMonth()+n,1);render()}
function selectDay(d){selected=d;setTab('Shifts')}
// --- Credentialing helpers (NBCRNA / AANA / state licenses) ---
// Data shape is intentionally Supabase-ready: these local records map to
// future tables nbcrna_profiles, aana_memberships, licenses and ce_records,
// each with a user_id (added at auth time). Nothing here is verified yet.
const US_STATES=['Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','District of Columbia','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'];
function daysUntil(dateStr){if(!dateStr)return null;const d=new Date(dateStr+'T12:00:00');if(Number.isNaN(d.getTime()))return null;const today=new Date(localDate(new Date())+'T12:00:00');return Math.round((d-today)/864e5)}
function parseReminders(s){const v=String(s||'90,60,30,7').split(',').map(x=>parseInt(x.trim(),10)).filter(x=>Number.isFinite(x)&&x>=0);return v.length?v:[90,60,30,7]}
function deadlineStatus(days){if(days===null)return null;if(days<0)return 'EXPIRED';return 'due'}
function portalLink(url){const u=String(url||'').trim();if(!u)return '';if(/^https?:\/\//i.test(u))return `<a href="${escapeHTML(u)}" target="_blank" rel="noopener">Official portal</a>`;return escapeHTML(u)}
function credentialDeadlines(){
  const items=[];
  const push=(label,date,reminders,source)=>{const days=daysUntil(date);if(days===null)return;if(days<0||parseReminders(reminders).some(w=>days<=w))items.push({label,date,days,source})};
  const n=db.nbcrna||{};push('NBCRNA certification',n.renewalDeadline||n.periodEnd,n.reminders,'NBCRNA');
  const a=db.aana||{};push('AANA membership',a.expiration,a.reminders,'AANA');
  (db.licenses||[]).forEach(x=>push((x.state||'License')+' '+(x.type||''),x.expiry,x.reminders,'State license'));
  (db.credentials||[]).forEach(x=>{const days=daysUntil(x.expiry);if(days!==null&&(days<0||days<=90))items.push({label:x.name||'Credential',date:x.expiry,days,source:'Credential'})});
  return items.sort((a,b)=>a.date.localeCompare(b.date));
}
function credentialDeadlinesPanel(){
  const items=credentialDeadlines();
  return `<section class="panel"><h2>Credential deadlines</h2><p class="muted">User-entered records only — nothing here is verified by NBCRNA, AANA, or a state board unless you mark it so. <a href="https://www.nbcrna.com/" target="_blank" rel="noopener">NBCRNA</a> · <a href="https://www.aana.com/" target="_blank" rel="noopener">AANA</a></p>${items.length?items.map(x=>`<div class="item"><strong>${escapeHTML(x.label)}</strong> · ${fmt(x.date)} <span class="${x.days<0?'expired':x.days<=7?'expired':x.days<=30?'warning':'success'}">${x.days<0?('Expired '+Math.abs(x.days)+' days ago'):(x.days===0?'Due today':('Due in '+x.days+' days'))}</span><div class="muted">${escapeHTML(x.source)}</div></div>`).join(''):'<p class="muted">No credential deadlines within their reminder windows.</p>'}</section>`;
}
function ceTotal(records,type){return records.filter(r=>!type||r.class===type).reduce((s,r)=>s+num(r.credits),0)}
function ceForm(kind,label,record){
  return `<form data-kind="${kind}"><div class="form-grid">${field('title','Course / activity','text',record.title||'','required')}${field('date','Date','date',record.date||localDate(new Date()))}${field('credits','Credits','number',record.credits??'','min="0" step="0.25"')}${kind==='nbcrnaCE'?select('class','Class',['Class A','Class B','Other'],record.class||'Class A'):field('note','Notes','text',record.note||'')}</div>${formEnd(editId?'Save CE record':'Add CE record')}</form>`;
}

// --- Ask Assistant (local-first) ---
// Local answer engine only: no network calls, no third-party AI service, no
// API key anywhere in this file. Answers about the user's own records are
// computed from the data already loaded in `db` (localStorage). Anything not
// in `db` is reported as missing, never invented. Facility notes are never
// quoted in answers (they may hold authorized facility codes), and no
// passwords or patient information are stored or shown here.
const ASSISTANT_STARTERS=['How can CRNA Hub help me?','What shifts do I have coming up?',"What's my projected income this month?",'What credentials are expiring soon?'];
function assistantClinical(q){return /\b(patient|diagnos|treatment|prescri|dosage|\bdose\b|drug interaction|intubat|airway management|anesthet\w+ (for|plan|technique)|clinical decision|symptom|disease)\b/i.test(q)}
function assistantUpcoming(){const now=localDate(new Date());return db.shifts.filter(x=>x.date>=now).sort((a,b)=>a.date.localeCompare(b.date))}
function assistantMonthShifts(){const prefix=localDate(new Date()).slice(0,7);return db.shifts.filter(x=>x.date?.startsWith(prefix))}
function answerQuestion(raw){
  const q=String(raw||'').trim();if(!q)return 'Ask me something — try one of the suggested questions below.';
  const l=q.toLowerCase();
  if(assistantClinical(q))return 'I can\'t answer clinical questions — CRNA Hub is an administrative assistant, not clinical decision support, and it holds no patient information. For a clinical question, check your facility protocols, a current clinical reference, or a qualified colleague. I can help with scheduling, income, credentials, mileage, and PTO instead.';
  if(/help me|what (can|does) (this|crna hub)|how (do|does) (this|crna hub|it) work|getting started|what is crna hub/.test(l))return 'CRNA Hub is your schedule, income, and professional life in one place. Use the Dashboard calendar to see shifts and expected gross, Shifts to add or import shifts (CSV), Facilities to store each hospital and its rates, Credentials for NBCRNA, AANA, and state licenses with 90/60/30/7-day reminders, Mileage to log and export business trips, and PTO to track a W-2 balance. Everything in this release is stored on this device only — no cloud sync yet, so export backups regularly.';
  if(/shift.*(coming|upcoming|next)|upcoming shift/.test(l)){const up=assistantUpcoming();if(!up.length)return 'You have no upcoming shifts recorded on this device. Add one from the Shifts tab, or import a schedule CSV.';const top=up.slice(0,5),total=up.reduce((s,x)=>s+num(x.pay),0);return `You have ${up.length} upcoming shift(s) recorded, worth ${currency(total)} in expected gross. Next up: ${top.map(x=>`${fmt(x.date)} at ${x.facility} (${x.type}, ${currency(x.pay)})`).join('; ')}${up.length>5?` — plus ${up.length-5} more.`:''}`}
  if(/income|projected|earn|gross|pay.*month|this month/.test(l)){const cur=assistantMonthShifts(),gross=cur.reduce((s,x)=>s+num(x.pay),0);if(!cur.length)return 'No shifts are recorded for this month, so I can\'t project income yet. Add shifts or import a CSV, and this answer will use them.';const by={};cur.forEach(x=>{by[x.facility||'Unknown']=(by[x.facility||'Unknown']||0)+num(x.pay)});return `Projected income this month, from recorded shifts only: ${currency(gross)} across ${cur.length} shift(s). By facility: ${Object.entries(by).map(([f,v])=>`${f} ${currency(v)}`).join('; ')}. Note: this build does not yet track confirmed vs. submitted vs. proposed status, so this is one combined total for all recorded shifts — not the separate confirmed / submitted-inclusive / proposed-inclusive forecasts in the product plan, and not paid income.`}
  if(/credential|license|nbcrna|aana|expir/.test(l)){const d=credentialDeadlines();if(!d.length)return 'No credential deadlines are inside their reminder windows right now, based on the records on this device. Check the Credentials tab to confirm your NBCRNA, AANA, and state license dates are entered.';return `Credentials needing attention: ${d.slice(0,8).map(x=>`${x.label} — ${fmt(x.date)} (${x.days<0?('expired '+Math.abs(x.days)+' days ago'):x.days===0?'due today':('due in '+x.days+' days')})`).join('; ')}. These are user-entered records — they are not verified by NBCRNA, AANA, or a state board until a live portal connection is added.`}
  if(/mileage|miles|trip/.test(l)){if(!db.mileage.length)return 'No mileage trips are logged yet. Log one from the Mileage tab, or generate schedule-based drafts there and confirm each trip.';const total=db.mileage.reduce((s,x)=>s+num(x.miles),0),draft=db.mileage.filter(x=>x.status==='draft').length;return `Mileage on this device: ${total.toFixed(1)} miles across ${db.mileage.length} trip(s), including ${draft} draft(s) still needing confirmation. Drafts are not verified trips — confirm the trip occurred and the actual miles before using them.`}
  if(/\bpto\b|time off|vacation/.test(l)){const bal=num(db.settings.ptoStarting)+db.pto.reduce((s,x)=>s+num(x.hours),0);return `Your recorded W-2 PTO balance is ${bal.toFixed(2)} hours, from ${db.pto.length} ledger entr(ies). This is what you recorded here — your employer's actual balance may differ.`}
  if(/facilit|hospital/.test(l)){if(!db.facilities.length)return 'No facilities are saved yet. Add one from the Facilities tab with its rates, and shifts can then use those rates.';return `You have ${db.facilities.length} facilit(ies) saved: ${db.facilities.map(f=>`${f.name} (8h ${currency(f.rate8)}, 24h ${currency(f.rate24)}, 2nd call ${currency(f.rateSecond)})`).join('; ')}. I don't quote facility notes here, since they may hold authorized facility codes.`}
  if(/contract|rate|pay.*(shift|call|hour)/.test(l))return 'Each facility stores a flat rate for 8-hour, 24-hour, and second-call shifts, and a shift with blank pay uses that facility rate. This build does not yet model weekday/weekend, hourly, overtime, holiday, or call-premium contract rules, and it does not yet read contracts — so I can explain the rates you entered, but I can\'t interpret a contract document yet.';
  if(/ce |continuing education|credits/.test(l)){const a=ceTotal(db.nbcrnaCE,'Class A'),b=ceTotal(db.nbcrnaCE,'Class B'),n=db.nbcrna||{},aa=db.aana||{};return `CE recorded here — NBCRNA: ${a} Class A and ${b} Class B credits from ${db.nbcrnaCE.length} record(s); MAC Ed ${n.macEd||0} of ${n.macEdRequired||60}, MAC Dev ${n.macDev||0} of ${n.macDevRequired||40}. AANA: ${ceTotal(db.aanaCE)} credits from ${db.aanaCE.length} record(s). These are user-entered totals, not a live AANA/NBCRNA transcript.`}
  if(/sync|cloud|supabase|account|sign ?in|backup/.test(l))return cloudAssistantAnswer();
  if(/c\/s\/p|confirmed|submitted|proposed|forecast/.test(l))return 'The planned income model splits forecasts into C (confirmed shifts only), S (confirmed + submitted, if all submitted dates are approved), and P (confirmed + submitted + proposed). This build does not track shift status yet, so it can only show one combined total for recorded shifts — the C/S/P split is a planned feature, not a live one.';
  return 'I can answer from what is actually recorded on this device: upcoming shifts, this month\'s projected income, credentials expiring soon, facilities and their rates, mileage, PTO, and CE totals — plus how CRNA Hub itself works. Try one of the suggested questions, or ask about one of those topics. I won\'t guess at records that aren\'t here, and I don\'t answer clinical questions.';
}
function assistantPage(){
  const hist=db.assistantChat||[];
  return `<section class="panel"><h2>Ask Assistant</h2><p class="muted">Local assistant — answers come only from this app and the records on this device. No live AI model is connected yet, and nothing is sent to any outside service. For account and cloud-sync status, see the Account tab. It cannot answer clinical questions and never shows facility codes, passwords, or patient information.</p><div class="chat">${hist.length?hist.map(m=>`<div class="msg ${m.role==='user'?'user':'assistant'}"><strong>${m.role==='user'?'You':'Assistant'}</strong><div>${escapeHTML(m.text)}</div></div>`).join(''):'<p class="muted">Ask about your schedule, income, credentials, mileage, or how CRNA Hub works.</p>'}</div><div class="toolbar" style="margin-top:12px">${ASSISTANT_STARTERS.map(q=>`<button type="button" class="secondary tiny" data-action="ask" data-id="${escapeHTML(q)}">${escapeHTML(q)}</button>`).join('')}</div><form id="assistantForm" class="chat-form"><label for="assistantInput" class="muted">Your question</label><input id="assistantInput" name="question" type="text" placeholder="Ask about your shifts, income, or credentials…" autocomplete="off"><button type="submit">Ask</button></form><div class="toolbar"><button type="button" class="secondary tiny" data-action="clear-chat">Clear chat history</button></div></section>`;
}
function submitAssistant(e){e.preventDefault();const input=$('assistantInput');if(!input)return;const q=input.value.trim();if(!q)return;db.assistantChat=[...(db.assistantChat||[]),{role:'user',text:q},{role:'assistant',text:answerQuestion(q)}].slice(-50);persist();render();const box=document.querySelector('.chat');if(box)box.scrollTop=box.scrollHeight}

function render(){ const ss=$('storageStatus');if(ss)ss.textContent=cloudHeaderLabel();$('nav').innerHTML=tabs.map(t=>`<button class="${tab===t?'active':''}" data-tab="${escapeHTML(t)}">${escapeHTML(t)}</button>`).join('');$('app').innerHTML=({Dashboard:dashboard,Shifts:shiftsPage,Facilities:facilitiesPage,PTO:ptoPage,Credentials:credentialsPage,Mileage:mileagePage,'Import & Backup':importPage,Assistant:assistantPage,Account:accountPage}[tab])();document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>actions(b.dataset.action,b.dataset.id,b.dataset.date)));document.querySelectorAll('form[data-kind]').forEach(f=>f.addEventListener('submit',submitEntry));const importForm=$('importForm');if(importForm)importForm.addEventListener('submit',importCsv);const restore=$('restoreFile');if(restore)restore.addEventListener('change',restoreBackup);const af=$('assistantForm');if(af)af.addEventListener('submit',submitAssistant);const cf=$('cloudAuthForm');if(cf)cf.addEventListener('submit',submitCloudAuth)}
function field(name,label,type='text',value='',extra=''){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra}></div>`}
function area(name,label,value='',placeholder=''){return `<div class="field wide"><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}" placeholder="${escapeHTML(placeholder)}">${escapeHTML(value)}</textarea></div>`}
function select(name,label,options,value){return `<div class="field"><label for="f_${name}">${label}</label><select name="${name}" id="f_${name}">${options.map(o=>`<option value="${escapeHTML(o)}" ${o===value?'selected':''}>${escapeHTML(o)}</option>`).join('')}</select></div>`}
function formEnd(label){return `<div class="form-actions"><button type="submit">${label}</button>${editId?'<button type="button" class="secondary" data-action="cancel">Cancel</button>':''}</div></form>`}
function list(kind,items,description){return items.length?items.map(x=>`<div class="item"><div>${description(x)}</div><div class="item-actions"><button class="tiny secondary" data-action="edit-${kind}" data-id="${escapeHTML(x.id)}">Edit</button><button class="tiny danger" data-action="delete-${kind}" data-id="${escapeHTML(x.id)}">Delete</button></div></div>`).join(''):'<p class="muted">No records yet.</p>'}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),prefix=`${y}-${String(m+1).padStart(2,'0')}`,start=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();let grid=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('');for(let n=0;n<start;n++)grid+='<div class="day blank"></div>';for(let n=1;n<=days;n++){const date=`${prefix}-${String(n).padStart(2,'0')}`,entries=db.shifts.filter(x=>x.date===date);grid+=`<button class="day ${date===localDate(new Date())?'today':''} ${date===selected?'selected':''}" data-action="day" data-date="${date}" aria-label="${fmt(date)}: ${entries.length} shifts"><span class="day-number">${n}</span>${entries.slice(0,3).map(x=>`<span class="chip ${/24.hour/i.test(x.type)?'call':/second/i.test(x.type)?'second':/off|pto/i.test(x.type)?'off':''}">${escapeHTML(x.facility||'Off')}<br>${escapeHTML(x.type||'Shift')}</span>`).join('')}${entries.length>3?`<span class="muted">+${entries.length-3}</span>`:''}</button>`}const shifts=db.shifts.filter(x=>x.date?.startsWith(prefix));return `<section class="panel"><div class="toolbar"><button class="secondary" data-action="prev" aria-label="Previous month">‹</button><h2>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><button class="secondary" data-action="next" aria-label="Next month">›</button><button class="secondary tiny" data-action="today">Today</button></div><div class="calendar">${grid}</div><p class="muted">${shifts.length} shifts · ${currency(shifts.reduce((s,x)=>s+num(x.pay),0))} expected gross · Tap a day to add a shift</p></section>`}
function dashboard(){const now=localDate(new Date()),prefix=now.slice(0,7),current=db.shifts.filter(x=>x.date?.startsWith(prefix)),gross=current.reduce((s,x)=>s+num(x.pay),0),upcoming=db.shifts.filter(x=>x.date>=now).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6),expiring=credentialDeadlines().length;return `<section class="panel"><h2>Overview · ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div class="stats"><div class="stat"><strong>${current.length}</strong>Shifts this month</div><div class="stat"><strong>${currency(gross)}</strong>Expected gross</div><div class="stat"><strong>${db.facilities.length}</strong>Facilities</div><div class="stat"><strong>${expiring}</strong>Credential deadlines (90 days)</div></div></section>${calendar()}${credentialDeadlinesPanel()}<div class="two"><section class="panel"><h2>Upcoming shifts</h2>${upcoming.length?upcoming.map(x=>`<div class="item"><strong>${fmt(x.date)}</strong> · ${escapeHTML(x.facility)}<div class="muted">${escapeHTML(x.type)} · ${currency(x.pay)}</div></div>`).join(''):'<p class="muted">No upcoming shifts.</p>'}</section><section class="panel"><h2>Quick actions</h2><div class="toolbar"><button data-action="add-shift">Add shift</button><button class="secondary" data-action="export-shifts">Export shifts</button><button class="secondary" data-action="backup">Back up data</button><button class="secondary" data-action="ask-assistant">Ask Assistant</button></div><p class="hint">${cloudModeHint()} Export backups regularly.</p></section></div>`}
function shiftsPage(){const x=db.shifts.find(x=>x.id===editId)||{},f=db.facilities;return `<div class="two"><section class="panel"><h2>${editId?'Edit':'Add'} shift</h2><form id="entryForm" data-kind="shifts"><div class="form-grid">${field('date','Date','date',x.date||selected,'required')}${field('facility','Hospital / facility','text',x.facility||'','list="facilityNames" required')}<datalist id="facilityNames">${f.map(a=>`<option value="${escapeHTML(a.name)}"></option>`).join('')}</datalist>${select('type','Shift type',['8-hour day','12-hour shift','24-hour call','Second call','Other','Off / PTO'],x.type||'8-hour day')}${field('pay','Expected gross pay ($)','number',x.pay??'','min="0" step="0.01" placeholder="Auto from facility"')}${area('note','Shift notes',x.note||'')}</div>${formEnd(editId?'Save changes':'Add shift')}<p class="muted">Leave pay blank to apply the saved facility rate for 8-hour, 24-hour, or second call shifts.</p></section><section class="panel"><h2>Shift totals</h2><div class="summary"><div><strong>${db.shifts.length}</strong><div class="muted">Total shifts</div></div><div><strong>${currency(db.shifts.reduce((s,x)=>s+num(x.pay),0))}</strong><div class="muted">All recorded gross</div></div></div><div class="toolbar"><button class="secondary" data-action="export-shifts">Export shifts CSV</button></div></section></div><section class="panel"><h2>Saved shifts</h2>${list('shifts',db.shifts.slice().sort((a,b)=>b.date.localeCompare(a.date)),x=>`<div class="item-title">${fmt(x.date)} · ${escapeHTML(x.facility)}</div><div class="muted">${escapeHTML(x.type)} · ${currency(x.pay)}</div>${x.note?`<p>${escapeHTML(x.note)}</p>`:''}`)}</section>`}
function facilitiesPage(){const x=db.facilities.find(x=>x.id===editId)||{};return `<section class="panel"><h2>${editId?'Edit':'Add'} hospital</h2><form id="entryForm" data-kind="facilities"><div class="form-grid">${field('name','Hospital / facility name','text',x.name||'','required')}${field('address','Address','text',x.address||'')}${field('rate8','8-hour shift rate ($)','number',x.rate8||'','min="0" step="0.01"')}${field('rate24','24-hour call rate ($)','number',x.rate24||'','min="0" step="0.01"')}${field('rateSecond','Second call rate ($)','number',x.rateSecond||'','min="0" step="0.01"')}${field('distance','One-way miles (manual)','number',x.distance||'','min="0" step="0.1"')}${area('notes','Offline facility notes',x.notes||'','Parking, protocols, phone numbers, authorized facility codes, EHR URL or username (never passwords)')}</div>${formEnd(editId?'Save facility':'Add facility')}</section><section class="panel"><h2>My facilities</h2>${list('facilities',db.facilities,x=>`<div class="item-title">${escapeHTML(x.name)}</div><div class="muted">${escapeHTML(x.address||'No address')} · 8h ${currency(x.rate8)} · 24h ${currency(x.rate24)} · 2nd ${currency(x.rateSecond)} · ${escapeHTML(x.distance||'—')} miles one-way</div>${x.notes?`<p style="white-space:pre-wrap">${escapeHTML(x.notes)}</p>`:''}`)}<p class="hint">Facility notes are stored unencrypted in this browser. Do not save passwords or patient information. Use authorized facility codes only on a trusted device.</p></section>`}
function ptoPage(){const x=db.pto.find(x=>x.id===editId)||{},balance=num(db.settings.ptoStarting)+db.pto.reduce((s,x)=>s+num(x.hours),0);return `<div class="two"><section class="panel"><h2>W-2 PTO balance</h2><div class="stat"><strong>${balance.toFixed(2)} hours</strong>Current recorded balance</div><p class="muted">Positive hours accrue; negative hours are PTO used. Your employer's actual balance may differ.</p><div class="form-grid">${field('starting','Starting balance (hours)','number',db.settings.ptoStarting||0,'step="0.25"')}${field('annual','Annual allowance (hours)','number',db.settings.ptoAnnual||0,'step="0.25"')}${field('perperiod','Accrual per pay period (hours)','number',db.settings.ptoHoursPerPeriod||0,'step="0.25"')}</div><div class="form-actions"><button data-action="save-pto-settings">Save PTO rules</button><button class="secondary" data-action="post-accrual">Post pay-period accrual</button></div></section><section class="panel"><h2>${editId?'Edit':'Record'} PTO</h2><form id="entryForm" data-kind="pto"><div class="form-grid">${field('date','Date','date',x.date||localDate(new Date()),'required')}${field('hours','Hours (+ earned / − used)','number',x.hours??'','step="0.25" required')}${field('note','Description','text',x.note||'')}</div>${formEnd(editId?'Save entry':'Record PTO')}</section></div><section class="panel"><h2>PTO ledger</h2>${list('pto',db.pto.slice().sort((a,b)=>b.date.localeCompare(a.date)),x=>`<strong>${fmt(x.date)}</strong> · <span class="${num(x.hours)<0?'expired':'success'}">${num(x.hours)>0?'+':''}${escapeHTML(x.hours)} hours</span><div class="muted">${escapeHTML(x.note||'')}</div>`)}</section>`}
function credentialsPage(){
  const n=db.nbcrna||{},a=db.aana||{},lic=db.licenses.find(x=>x.id===editId)||{},nce=db.nbcrnaCE.find(x=>x.id===editId)||{},ace=db.aanaCE.find(x=>x.id===editId)||{},legacy=db.credentials.find(x=>x.id===editId)||{};
  const nbcrnaDays=daysUntil(n.renewalDeadline||n.periodEnd),aanaDays=daysUntil(a.expiration);
  const connCard=(title,desc,pulls,manualNote,siteLabel,siteUrl,portalKey)=>{const st=cloudPortalState(portalKey);return `<section class="panel"><h2>${title}</h2><p><strong>Status: ${escapeHTML(st.label)}</strong>${st.detail?` — ${escapeHTML(st.detail)}`:''}</p><p class="muted">${desc}</p><p class="muted">Would pull automatically when a portal connection exists: ${pulls}</p><p class="muted">${manualNote}</p><p class="muted">Official site: <a href="${siteUrl}" target="_blank" rel="noopener">${siteLabel}</a></p><div class="toolbar"><button type="button" class="secondary" data-action="connect-portal" data-id="${title}">Connect ${title}</button></div></section>`};
  const nbcrnaManual=(n.status||n.number||n.renewalDeadline||n.periodEnd)?'Manual fallback record on file (user-entered, not verified).':'No manual fallback record on file yet.';
  const aanaManual=(a.status||a.number||a.expiration)?'Manual fallback record on file (user-entered, not verified).':'No manual fallback record on file yet.';
  const licManual=db.licenses.length?db.licenses.length+' manual fallback license record(s) on file (user-entered, not verified).':'No manual fallback license records on file yet.';
  return `<p class="hint">Connect-first: NBCRNA, AANA, and state nursing portals are meant to pull your information automatically when connected, with minimal manual entry. That automatic pull is <strong>not available yet</strong> — it needs a server-side Edge Function, which is not built yet (see the Account tab). What ${cloudSession?'your signed-in account does sync':'signing in on the Account tab would sync'} is the records below, between this device and your Supabase account — it never pulls a portal and never verifies a record. Until a portal pull exists, the sections under "Manual entry (fallback only)" are the only way to record credentials, and every record there is <strong>user-entered, not verified</strong>. No portal passwords are stored here, and nothing on this page scrapes a portal.</p>
  ${connCard('NBCRNA','National Board of Certification and Recertification for Nurse Anesthetists — your certification record.','certification status, certification period, renewal / recertification deadline, MAC Ed / MAC Dev progress, and CPC check-in status.',nbcrnaManual,'nbcrna.com','https://www.nbcrna.com/','nbcrna')}
  ${connCard('AANA','American Association of Nurse Anesthesiology — your membership and CE transcript. Kept separate from NBCRNA certification.','membership status, membership expiration, and CE transcript totals (Class A / Class B).',aanaManual,'aana.com','https://www.aana.com/','aana')}
  ${connCard('State Licenses','State boards of nursing — RN and APRN licenses, one connection per state you hold a license in.','license status, license type (RN / APRN), license number, issue date, and expiration date.',licManual,'State board portals (per license, below)','https://www.nursys.com/','licenses')}
  <h2>Manual entry (fallback only)</h2><p class="muted">Use these sections only until the portal connections above are live. All records here are user-entered, not verified by NBCRNA, AANA, or any state board. No automatic verification, API sync, or document upload is available in this release — document fields hold a filename or note only. Do not store patient information or portal passwords.</p>
  <section class="panel"><h2>NBCRNA certification</h2><p class="muted">Official site: <a href="https://www.nbcrna.com/" target="_blank" rel="noopener">nbcrna.com</a> · Status shown: ${escapeHTML(n.status||'Not entered')}${nbcrnaDays!==null?` · Renewal in ${nbcrnaDays<0?Math.abs(nbcrnaDays)+' days overdue':nbcrnaDays+' days'}`:''}</p>
  <form data-kind="nbcrna"><div class="form-grid">${select('status','Certification status',['','Certified','Pending','Expired','Not certified'],n.status||'')}${field('number','Certification number (optional)','text',n.number||'')}${field('periodStart','Certification period start','date',n.periodStart||'')}${field('periodEnd','Certification period end','date',n.periodEnd||'')}${field('renewalDeadline','Renewal / recertification deadline','date',n.renewalDeadline||'')}${field('classA','Class A credits earned','number',n.classA??'','min="0" step="0.25"')}${field('classB','Class B credits earned','number',n.classB??'','min="0" step="0.25"')}${field('macEd','MAC Ed credits earned','number',n.macEd??'','min="0" step="0.25"')}${field('macDev','MAC Dev credits earned','number',n.macDev??'','min="0" step="0.25"')}${field('macEdRequired','MAC Ed credits required','number',n.macEdRequired??60,'min="0" step="1"')}${field('macDevRequired','MAC Dev credits required','number',n.macDevRequired??40,'min="0" step="1"')}${field('reminders','Reminder windows (days, comma-separated)','text',n.reminders||'90,60,30,7')}${field('docNote','Supporting document note (filename only)','text',n.docNote||'')}${area('ceNote','CE notes',n.ceNote||'')}</div>${formEnd('Save NBCRNA record')}</form>
  <h3>NBCRNA CE records (user-entered)</h3><p class="muted">Recorded totals — Class A: ${ceTotal(db.nbcrnaCE,'Class A')} · Class B: ${ceTotal(db.nbcrnaCE,'Class B')} · All: ${ceTotal(db.nbcrnaCE)}</p>${ceForm('nbcrnaCE','NBCRNA CE',nce)}
  ${list('nbcrnaCE',db.nbcrnaCE.slice().sort((a,b)=>b.date.localeCompare(a.date)),x=>`<strong>${escapeHTML(x.title)}</strong> · ${fmt(x.date)} · ${escapeHTML(x.credits||'—')} credits · ${escapeHTML(x.class||'')}`)}</section>
  <section class="panel"><h2>AANA membership</h2><p class="muted">Kept separate from NBCRNA certification. Official site: <a href="https://www.aana.com/" target="_blank" rel="noopener">aana.com</a> · Status shown: ${escapeHTML(a.status||'Not entered')}${aanaDays!==null?` · Expires in ${aanaDays<0?Math.abs(aanaDays)+' days overdue':aanaDays+' days'}`:''}</p>
  <form data-kind="aana"><div class="form-grid">${select('status','Membership status',['','Active','Lapsed','Pending','Not a member'],a.status||'')}${field('number','Membership number (optional)','text',a.number||'')}${field('expiration','Membership expiration','date',a.expiration||'')}${field('reminders','Reminder windows (days, comma-separated)','text',a.reminders||'90,60,30,7')}${field('docNote','Supporting document note (filename only)','text',a.docNote||'')}${area('ceNote','CE documentation notes',a.ceNote||'')}</div>${formEnd('Save AANA record')}</form>
  <h3>AANA CE records (user-entered)</h3><p class="muted">Recorded total: ${ceTotal(db.aanaCE)} credits</p>${ceForm('aanaCE','AANA CE',ace)}
  ${list('aanaCE',db.aanaCE.slice().sort((a,b)=>b.date.localeCompare(a.date)),x=>`<strong>${escapeHTML(x.title)}</strong> · ${fmt(x.date)} · ${escapeHTML(x.credits||'—')} credits${x.note?` · ${escapeHTML(x.note)}`:''}`)}</section>
  <section class="panel"><h2>State licenses</h2><form data-kind="licenses"><div class="form-grid">${select('state','State',US_STATES,lic.state||'West Virginia')}${select('type','License type',['RN','APRN'],lic.type||'RN')}${field('number','License number','text',lic.number||'')}${field('issue','Issue date','date',lic.issue||'')}${field('expiry','Expiration date','date',lic.expiry||'','required')}${field('portal','Official board portal (URL or name)','text',lic.portal||'')}${field('reminders','Reminder windows (days, comma-separated)','text',lic.reminders||'90,60,30,7')}${area('note','Notes',lic.note||'')}</div>${formEnd(editId&&db.licenses.some(x=>x.id===editId)?'Save license':'Add license')}</form>
  ${list('licenses',db.licenses.slice().sort((a,b)=>a.expiry.localeCompare(b.expiry)),x=>{const d=daysUntil(x.expiry);return `<strong>${escapeHTML(x.state||'')} ${escapeHTML(x.type||'')}</strong> · ${x.number?escapeHTML(x.number)+' · ':''}${fmt(x.expiry)} <span class="${d!==null&&d<0?'expired':d!==null&&d<=7?'expired':d!==null&&d<=30?'warning':'success'}">${d===null?'':d<0?('Expired '+Math.abs(d)+' days ago'):d===0?'Due today':('Due in '+d+' days')}</span><div class="muted">${portalLink(x.portal)} ${escapeHTML(x.note||'')}</div>`})}</section>
  <section class="panel"><h2>Other credentials (existing records)</h2><p class="muted">Generic credentials from earlier versions are preserved here, unchanged.</p><form data-kind="credentials"><div class="form-grid">${field('name','Credential / license','text',legacy.name||'','required')}${field('expiry','Expiration date','date',legacy.expiry||'','required')}${field('issuer','Issuer / state','text',legacy.issuer||'')}${area('note','Notes',legacy.note||'')}</div>${formEnd(editId&&db.credentials.some(x=>x.id===editId)?'Save credential':'Add credential')}</form>
  ${list('credentials',db.credentials.slice().sort((a,b)=>a.expiry.localeCompare(b.expiry)),x=>`<strong>${escapeHTML(x.name)}</strong> · ${fmt(x.expiry)} <span class="${x.expiry<localDate(new Date())?'expired':x.expiry<=localDate(new Date(Date.now()+30*864e5))?'warning':'success'}">${x.expiry<localDate(new Date())?'EXPIRED':x.expiry<=localDate(new Date(Date.now()+30*864e5))?'Due within 30 days':'Current'}</span><div class="muted">${escapeHTML(x.issuer||'')} ${escapeHTML(x.note||'')}</div>`)}</section>`;
}
function mileagePage(){const x=db.mileage.find(x=>x.id===editId)||{},total=db.mileage.reduce((s,x)=>s+num(x.miles),0);return `<div class="two"><section class="panel"><h2>${editId?'Edit':'Log'} business mileage</h2><form id="entryForm" data-kind="mileage"><div class="form-grid">${field('date','Trip date','date',x.date||localDate(new Date()),'required')}${field('miles','Actual miles','number',x.miles??'','min="0" step="0.1" required')}${field('purpose','Business purpose','text',x.purpose||'','required')}${select('status','Verification',['verified','draft'],x.status||'verified')}</div>${formEnd(editId?'Save trip':'Log trip')}</section><section class="panel"><h2>Mileage summary</h2><div class="stat"><strong>${total.toFixed(1)} miles</strong>All logged and draft trips</div><div class="toolbar" style="margin-top:14px"><button data-action="mileage-drafts">Generate schedule-based drafts</button><button class="secondary" data-action="export-mileage">Export CSV</button></div><p class="hint">Drafts use twice the facility's manually entered one-way distance. Confirm the trip actually occurred, actual miles, and tax eligibility. Regular commuting is generally not deductible.</p></section></div><section class="panel"><h2>Trip log</h2>${list('mileage',db.mileage.slice().sort((a,b)=>b.date.localeCompare(a.date)),x=>`<strong>${fmt(x.date)}</strong> · ${escapeHTML(x.miles)} mi <span class="pill">${escapeHTML(x.status||'verified')}</span><div class="muted">${escapeHTML(x.purpose)}</div>`)}</section>`}
function importPage(){return `<section class="panel"><h2>Import a schedule</h2><p>Import a CSV file with columns <code>date,facility,type,pay</code>. The pay column is optional; missing pay uses saved facility rates. Dates must be YYYY-MM-DD.</p><form id="importForm"><div class="form-grid">${field('importFile','Choose CSV file','file','','accept=".csv,text/csv"')}${area('importText','Or paste CSV rows','','date,facility,type,pay\n2026-11-05,CAMC,8-hour day,2000')}</div><div class="form-actions"><button type="submit">Import schedule</button></div></form><p class="hint">Excel (.xlsx), PDF and screenshot OCR are not implemented in this local-first release. Export the spreadsheet as CSV first. Never upload patient information.</p></section><section class="panel"><h2>Backup & restore</h2><p class="muted">Back up before changing phones, clearing browser data, or replacing the website.</p><p class="muted">Current mode: <strong>${escapeHTML(cloudHeaderLabel())}</strong>. A backup restores records onto this device only — it never overwrites your cloud account. To push restored records to the cloud, use "Upload my on-device records" on the Account tab.</p><div class="toolbar"><button data-action="backup">Download JSON backup</button><button class="secondary" data-action="export-shifts">Download shift CSV</button><button class="secondary" data-action="export-mileage">Download mileage CSV</button></div><label for="restoreFile">Restore a CRNA Hub JSON backup (replaces current records)</label><input id="restoreFile" type="file" accept=".json,application/json"></section><section class="panel"><h2>What comes next</h2><p class="muted">Supabase sign-in and credential sync are on the Account tab (${SUPABASE_CONFIGURED?'configured — sign in to use them':'not configured yet — paste the publishable key into supabase-config.js, see the README'}). Live NBCRNA / AANA / state portal pulls still need a server-side Edge Function and are not represented as working features here. Also still unbuilt: secure multi-user W-2 scheduling, screenshot/PDF/Excel recognition, commute-aware alarm rules, and automatic mileage detection.</p></section>`}
function submitEntry(e){e.preventDefault();const kind=e.currentTarget.dataset.kind,record=Object.fromEntries(new FormData(e.currentTarget));if(kind==='nbcrna'||kind==='aana'){db[kind]={...(db[kind]||{}),...record};persist();cloudSaveKind(kind);render();return;}if(kind==='shifts'&&!String(record.pay).trim()){const f=db.facilities.find(x=>x.name.trim().toLowerCase()===record.facility.trim().toLowerCase());record.pay=f?(/24.hour/i.test(record.type)?num(f.rate24):/second/i.test(record.type)?num(f.rateSecond):/8.hour/i.test(record.type)?num(f.rate8):0):0}if(kind==='facilities'&&db.facilities.some(x=>x.name.toLowerCase()===record.name.toLowerCase()&&x.id!==editId)){alert('A facility with that name already exists.');return}let savedId=editId;if(editId){const i=db[kind].findIndex(x=>x.id===editId);if(i>=0)db[kind][i]={...db[kind][i],...record}}else{const rec={...record,id:id()};db[kind].push(rec);savedId=rec.id}editId=null;persist();if(['licenses','nbcrnaCE','aanaCE'].includes(kind))cloudSaveKind(kind,savedId);render()}
function actions(action,entry,date){if(action==='prev')return moveMonth(-1);if(action==='next')return moveMonth(1);if(action==='today'){month=new Date();month.setDate(1);selected=localDate(new Date());return render()}if(action==='day')return selectDay(date);if(action==='add-shift')return setTab('Shifts');if(action==='ask-assistant')return setTab('Assistant');if(action==='connect-portal'){if(!SUPABASE_CONFIGURED){alert('Supabase is not configured yet: paste the publishable key into supabase-config.js (see the Account tab and README), then redeploy. Until then this button cannot connect anything.');return setTab('Account')}if(!cloudSession){alert('Sign in on the Account tab first. Signing in syncs the records you enter here to your Supabase account — it does not pull a portal yet.\n\nAutomatic portal pulls need a server-side Edge Function, which is not built yet. What the '+entry+' card would pull once that exists is listed on the card above. Until then, use the "Manual entry (fallback only)" sections below — those records are user-entered, not verified.');return setTab('Account')}alert('Your account is signed in, so the records you enter here sync to Supabase — but this button still cannot pull the '+entry+' portal today.\n\nAutomatic portal pulls need a server-side Edge Function, which is not built yet. What it will pull once that exists is listed on the card above. Until then, use the "Manual entry (fallback only)" sections below — those records are user-entered, not verified. No portal passwords are stored here.');window.scrollTo(0,document.body.scrollHeight);return;}if(action==='ask'){db.assistantChat=[...(db.assistantChat||[]),{role:'user',text:entry},{role:'assistant',text:answerQuestion(entry)}].slice(-50);persist();return render()}if(action==='clear-chat'){db.assistantChat=[];persist();return render()}if(action==='cancel'){editId=null;return render()}if(action.startsWith('edit-')){const kind=action.slice(5);tab=({shifts:'Shifts',facilities:'Facilities',pto:'PTO',credentials:'Credentials',mileage:'Mileage',licenses:'Credentials',nbcrnaCE:'Credentials',aanaCE:'Credentials'})[kind];editId=entry;render();window.scrollTo(0,0);return}if(action.startsWith('delete-')){const kind=action.slice(7);if(!confirm('Delete this record?'))return;db[kind]=db[kind].filter(x=>x.id!==entry);persist();if(['licenses','nbcrnaCE','aanaCE'].includes(kind))cloudDeleteKind(kind,entry);return render()}if(action==='save-pto-settings'){db.settings.ptoStarting=num($('f_starting').value);db.settings.ptoAnnual=num($('f_annual').value);db.settings.ptoHoursPerPeriod=num($('f_perperiod').value);persist();return render()}if(action==='post-accrual'){const h=num(db.settings.ptoHoursPerPeriod);if(h<=0)return alert('Set the pay-period accrual first.');db.pto.push({id:id(),date:localDate(new Date()),hours:String(h),note:'Pay-period accrual'});persist();return render()}if(action==='mileage-drafts')return makeMileageDrafts();if(action==='cloud-signup'){const em=$('f_email'),pw=$('f_password');if(!em||!pw||!em.value.trim()||!pw.value)return alert('Enter an email and password first.');cloudSignUp(em.value.trim(),pw.value);return}
if(action==='cloud-upload'){if(!confirm('Upload on-device credential records to your cloud account? This overwrites the credential records currently stored in your cloud account (NBCRNA, AANA, licenses, CE records) with the ones on this device. Shifts, facilities, mileage, and PTO are not uploaded.'))return;cloudUploadLocal();return}
if(action==='cloud-load'){if(!confirm('Load cloud credential records onto this device? This replaces the NBCRNA, AANA, license, and CE records on this device with the ones in your cloud account. Shifts, facilities, mileage, and PTO are untouched.'))return;cloudLoadIntoLocal();return}
if(action==='cloud-sync'){if(!confirm('Sync now downloads your cloud credential records onto this device, replacing the NBCRNA, AANA, license, and CE records here. Continue?'))return;cloudLoadIntoLocal();return}
if(action==='cloud-signout'){cloudSignOut();return}
if(action==='cloud-keep-local'){cloudPending=null;render();return}
if(action==='goto-account')return setTab('Account');
if(action==='backup')return download('crna-hub-backup.json',JSON.stringify({...db,_backupMeta:{mode:cloudMode(),account:cloudSession?cloudSession.email:null,exportedAt:new Date().toISOString(),note:'Cloud vs on-device mode at export time. Restore loads records onto this device only; it never overwrites the cloud account.'}},null,2),'application/json');if(action==='export-shifts')return exportCsv('crna-hub-shifts.csv',['date','facility','type','pay','note'],db.shifts);if(action==='export-mileage')return exportCsv('crna-hub-mileage.csv',['date','purpose','miles','status'],db.mileage)}
function makeMileageDrafts(){let count=0;for(const x of db.shifts){if(/off|pto/i.test(x.type))continue;const f=db.facilities.find(f=>f.name.trim().toLowerCase()===String(x.facility).trim().toLowerCase());if(!f||num(f.distance)<=0)continue;const purpose='Scheduled facility trip: '+f.name;if(db.mileage.some(m=>m.date===x.date&&m.purpose===purpose))continue;db.mileage.push({id:id(),date:x.date,purpose,miles:String((num(f.distance)*2).toFixed(1)),status:'draft'});count++}persist();render();alert(`${count} mileage draft(s) created. Review every trip and tax eligibility before using them.`)}
function csvEscape(v){const s=String(v??'');return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function exportCsv(filename,headers,rows){download(filename,[headers.join(','),...rows.map(r=>headers.map(h=>csvEscape(r[h])).join(','))].join('\r\n'),'text/csv;charset=utf-8')}
function download(filename,contents,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([contents],{type:mime}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function parseCSV(str){const rows=[],row=[];let cell='',quote=false;for(let i=0;i<str.length;i++){const c=str[i];if(c==='"'){if(quote&&str[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&str[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row.slice());row.length=0;cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
async function importCsv(e){e.preventDefault();const f=$('f_importFile').files[0],input=f?await f.text():$('f_importText').value,rows=parseCSV(input.replace(/^\uFEFF/,''));let count=0,skipped=0;for(let i=0;i<rows.length;i++){const r=rows[i].map(x=>x.trim());if(i===0&&/date/i.test(r[0])&&!/^\d{4}-\d{2}-\d{2}$/.test(r[0]))continue;if(!/^\d{4}-\d{2}-\d{2}$/.test(r[0])||Number.isNaN(Date.parse(r[0]+'T12:00:00'))||!r[1]){skipped++;continue}const facility=r[1],type=r[2]||'Other',f=db.facilities.find(x=>x.name.toLowerCase()===facility.toLowerCase()),pay=r[3]!==undefined&&r[3]!==''?num(r[3]):f?(/24.hour/i.test(type)?num(f.rate24):/second/i.test(type)?num(f.rateSecond):/8.hour/i.test(type)?num(f.rate8):0):0;if(db.shifts.some(x=>x.date===r[0]&&x.facility===facility&&x.type===type)){skipped++;continue}db.shifts.push({id:id(),date:r[0],facility,type,pay:String(pay),note:'CSV import'});count++}persist();render();alert(`Imported ${count} shift(s); skipped ${skipped} invalid or duplicate row(s).`)}
async function restoreBackup(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());for(const key of ['shifts','facilities','pto','credentials','mileage'])if(!Array.isArray(data[key]))throw Error('Missing or invalid '+key);if(!confirm('Replace all current records with this backup?'))return;const next=empty();for(const k of ['shifts','facilities','pto','credentials','mileage'])next[k]=data[k];if(data.settings&&typeof data.settings==='object')next.settings=data.settings;if(data.nbcrna&&typeof data.nbcrna==='object')next.nbcrna=data.nbcrna;if(data.aana&&typeof data.aana==='object')next.aana=data.aana;if(Array.isArray(data.nbcrnaCE))next.nbcrnaCE=data.nbcrnaCE;if(Array.isArray(data.aanaCE))next.aanaCE=data.aanaCE;if(Array.isArray(data.licenses))next.licenses=data.licenses;if(Array.isArray(data.assistantChat))next.assistantChat=data.assistantChat;db=next;persist();render();alert(cloudActive&&cloudSession?'Backup restored onto this device only. It did NOT overwrite your cloud account. To push these records to the cloud, use "Upload my on-device records" on the Account tab.':'Backup restored.')}catch(err){alert('Could not restore backup: '+err.message)}}

// --- Supabase Auth + credential sync (fetch-based, no extra dependency) ---
// Reads/writes ONLY the five migration-001 tables, with user_id = auth uid.
// Row Level Security on those tables restricts every row to its owner.
// Shifts, facilities, mileage, and PTO are NOT synced in this release: they
// stay on-device, and the Account tab says so. Live NBCRNA / AANA / state
// portal pulls are NOT part of this section: they need a server-side Edge
// Function (next phase) and are never faked from the browser.
// Safety rule: cloud data is never overwritten silently. On first sign-in
// the user must explicitly choose "Upload my on-device records" or
// "Load cloud records" on the Account tab; until then edits stay local.
const SUPABASE_CFG = (typeof window !== 'undefined' && window.CRNHUB_SUPABASE) || {};
const SUPABASE_CONFIGURED = !!(SUPABASE_CFG.url && SUPABASE_CFG.anonKey && String(SUPABASE_CFG.anonKey).indexOf('PASTE') === -1);
let cloudSession = null, cloudActive = false, cloudPending = null, cloudOffline = false, cloudError = '', cloudLastSync = '', cloudSyncTimes = {};
try { cloudSession = JSON.parse(localStorage.getItem('crna-hub-supabase-session') || 'null'); cloudActive = localStorage.getItem('crna-hub-cloud-active') === '1'; cloudLastSync = localStorage.getItem('crna-hub-last-sync') || ''; } catch (e) {}
function cloudPersistSession() { try { if (cloudSession) localStorage.setItem('crna-hub-supabase-session', JSON.stringify(cloudSession)); else localStorage.removeItem('crna-hub-supabase-session'); localStorage.setItem('crna-hub-cloud-active', cloudActive ? '1' : '0'); if (cloudLastSync) localStorage.setItem('crna-hub-last-sync', cloudLastSync); } catch (e) {} }
function cloudMode() { if (!SUPABASE_CONFIGURED) return 'not-configured'; if (!cloudSession) return 'signed-out'; if (cloudPending) return 'pending'; if (!cloudActive) return 'signed-out'; return cloudOffline ? 'cloud-offline' : 'cloud'; }
function cloudSyncEnabled() { return SUPABASE_CONFIGURED && !!cloudSession && cloudActive && !cloudPending; }
function cloudHeaderLabel() { const m = cloudMode(); if (m === 'not-configured') return 'Supabase not configured'; if (m === 'signed-out') return cloudSession ? 'Signed in · Choose sync on Account' : 'On this device · Not signed in'; if (m === 'pending') return 'Signed in · Choose sync on Account'; if (m === 'cloud-offline') return 'Cloud (offline) · On-device copy'; return 'Cloud · ' + (cloudSession.email || 'signed in'); }
function cloudModeHint() { const m = cloudMode(); if (m === 'not-configured') return 'Supabase is not configured yet, so everything here is saved on this device only.'; if (m === 'signed-out') return 'Not signed in, so everything here is saved on this device only.'; if (m === 'pending') return 'Signed in, but you have not chosen upload or load yet, so edits here are still on-device only — choose on the Account tab.'; if (m === 'cloud-offline') return 'Cloud account is unreachable right now, so this is the on-device copy. Credential edits will retry on the next sync.'; return 'Signed in — credential records sync to your Supabase account. Shifts, facilities, mileage, and PTO stay on this device.'; }
function cloudAssistantAnswer() { if (!SUPABASE_CONFIGURED) return 'Cloud accounts and sync are not in this release on this device yet: Supabase is not configured (paste the publishable key into supabase-config.js — see the README), so data lives in this browser only (localStorage). Use Import & Backup to download a JSON backup before changing phones or clearing browser data.'; if (!cloudSession) return 'You are not signed in, so data lives in this browser only (localStorage). Sign in on the Account tab to sync NBCRNA, AANA, license, and CE records to your Supabase account. Use Import & Backup to download a JSON backup before changing phones or clearing browser data.'; if (cloudPending) return 'You are signed in, but you have not chosen how to merge yet, so records are still on-device only. Open the Account tab and choose "Upload my on-device records" or "Load cloud records".'; return 'You are signed in and credential records (NBCRNA, AANA, licenses, CE records) sync to your Supabase account; shifts, facilities, mileage, and PTO stay on this device. Live portal pulls are not built yet, so synced records are still user-entered, not verified.'; }
function cloudFmtWhen(iso) { try { return new Date(iso).toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }); } catch (e) { return ''; } }
async function sbAuthReq(path, body) { const r = await fetch(SUPABASE_CFG.url + path, { method: 'POST', headers: { apikey: SUPABASE_CFG.anonKey, 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); const text = await r.text(); let data = null; try { data = text ? JSON.parse(text) : null; } catch (e) {} if (!r.ok) throw new Error((data && (data.error_description || data.msg || data.message || data.error)) || ('Sign-in failed (' + r.status + ')')); return data; }
function cloudStoreSession(data) { if (!data || !data.access_token) return false; cloudSession = { access_token: data.access_token, refresh_token: data.refresh_token || (cloudSession && cloudSession.refresh_token), expires_at: Math.floor(Date.now() / 1000) + (data.expires_in || 3600), email: (data.user && data.user.email) || (cloudSession && cloudSession.email) || '', user_id: (data.user && data.user.id) || (cloudSession && cloudSession.user_id) || '' }; cloudPersistSession(); return true; }
async function cloudEnsureToken() { if (!cloudSession) throw new Error('Not signed in'); if (cloudSession.expires_at && Date.now() / 1000 < cloudSession.expires_at - 60) return; if (!cloudSession.refresh_token) throw new Error('Session expired — sign in again'); const data = await sbAuthReq('/auth/v1/token?grant_type=refresh_token', { refresh_token: cloudSession.refresh_token }); if (!cloudStoreSession(data)) throw new Error('Session expired — sign in again'); }
async function sbReq(path, method, body) { await cloudEnsureToken(); const headers = { apikey: SUPABASE_CFG.anonKey, 'Content-Type': 'application/json', Authorization: 'Bearer ' + cloudSession.access_token }; if (method === 'POST' && body) headers.Prefer = 'resolution=merge-duplicates,return=minimal'; const r = await fetch(SUPABASE_CFG.url + path, { method, headers, body: body ? JSON.stringify(body) : undefined }); const text = await r.text(); let data = null; try { data = text ? JSON.parse(text) : null; } catch (e) {} if (!r.ok) throw new Error((data && (data.message || data.msg || data.error_description)) || ('Sync failed (' + r.status + ')')); return data; }
function cloudUid() { return cloudSession ? cloudSession.user_id : ''; }
async function cloudFetchAll() { const uid = cloudUid(), q = '?select=*&user_id=eq.' + encodeURIComponent(uid); const nb = await sbReq('/rest/v1/nbcrna_profiles' + q, 'GET'); const aa = await sbReq('/rest/v1/aana_memberships' + q, 'GET'); const lic = await sbReq('/rest/v1/licenses' + q, 'GET'); const ce = await sbReq('/rest/v1/ce_records' + q, 'GET'); const portals = await sbReq('/rest/v1/portal_connections' + q, 'GET'); return { nbcrna: (nb && nb[0]) || null, aana: (aa && aa[0]) || null, licenses: lic || [], ce: ce || [], portals: portals || [] }; }
function cloudCountsOf(data) { return { nbcrna: data.nbcrna ? 1 : 0, aana: data.aana ? 1 : 0, licenses: (data.licenses || []).length, ce: (data.ce || []).length }; }
function cloudLocalHasNbcrna() { const n = db.nbcrna || {}; return !!(n.status || n.number || n.periodStart || n.periodEnd || n.renewalDeadline); }
function cloudLocalHasAana() { const a = db.aana || {}; return !!(a.status || a.number || a.expiration); }
function cloudLocalHasRecords() { return cloudLocalHasNbcrna() || cloudLocalHasAana() || (db.licenses || []).length > 0 || (db.nbcrnaCE || []).length > 0 || (db.aanaCE || []).length > 0; }
function cloudLocalCounts() { return { nbcrna: cloudLocalHasNbcrna() ? 1 : 0, aana: cloudLocalHasAana() ? 1 : 0, licenses: (db.licenses || []).length, ce: (db.nbcrnaCE || []).length + (db.aanaCE || []).length }; }
function cloudNumOrNull(v) { if (v === '' || v === null || v === undefined) return null; const n = Number(v); return Number.isFinite(n) ? n : null; }
function cloudNow() { return new Date().toISOString(); }
function cloudNbcrnaRow() { const n = db.nbcrna || {}; return { user_id: cloudUid(), certification_status: n.status || null, certification_number: n.number || null, period_start: n.periodStart || null, period_end: n.periodEnd || null, renewal_deadline: n.renewalDeadline || null, class_a_credits: cloudNumOrNull(n.classA), class_b_credits: cloudNumOrNull(n.classB), mac_ed_credits: cloudNumOrNull(n.macEd), mac_dev_credits: cloudNumOrNull(n.macDev), mac_ed_required: cloudNumOrNull(n.macEdRequired) || 60, mac_dev_required: cloudNumOrNull(n.macDevRequired) || 40, cpc_check_in_status: null, source: 'user_entered', last_synced_at: cloudNow() }; }
function cloudAanaRow() { const a = db.aana || {}; return { user_id: cloudUid(), membership_status: a.status || null, membership_number: a.number || null, expiration: a.expiration || null, source: 'user_entered', last_synced_at: cloudNow() }; }
function cloudLicenseRow(x) { return { id: x.id, user_id: cloudUid(), state: x.state, license_type: x.type, license_number: x.number || null, issue_date: x.issue || null, expiration_date: x.expiry || null, status: null, board_portal_url: x.portal || null, notes: x.note || null, source: 'user_entered', last_synced_at: cloudNow() }; }
function cloudCeRow(x, source) { return { id: x.id, user_id: cloudUid(), source: source, title: x.title || null, credits: cloudNumOrNull(x.credits) || 0, credit_class: source === 'nbcrna' ? (x.class || null) : null, completed_date: x.date || null }; }
async function cloudUpsertPortals() { const states = []; (db.licenses || []).forEach(x => { if (x.state && states.indexOf(x.state) === -1) states.push(x.state); }); const desired = [{ portal: 'nbcrna', state: null }, { portal: 'aana', state: null }].concat(states.map(st => ({ portal: 'state_board', state: st }))); let existing = []; try { existing = await sbReq('/rest/v1/portal_connections?select=*&user_id=eq.' + encodeURIComponent(cloudUid()), 'GET'); } catch (e) { existing = []; } const rows = desired.map(d => { const match = (existing || []).find(e => e.portal === d.portal && (e.state || null) === (d.state || null)); return { id: match ? match.id : id(), user_id: cloudUid(), portal: d.portal, state: d.state, status: 'connected', last_synced_at: cloudNow(), last_error: null }; }); if (rows.length) await sbReq('/rest/v1/portal_connections', 'POST', rows); }
async function cloudUploadLocal() { if (!cloudSession) return; try { const rows = []; if (cloudLocalHasNbcrna()) rows.push(sbReq('/rest/v1/nbcrna_profiles', 'POST', cloudNbcrnaRow())); if (cloudLocalHasAana()) rows.push(sbReq('/rest/v1/aana_memberships', 'POST', cloudAanaRow())); if ((db.licenses || []).length) rows.push(sbReq('/rest/v1/licenses', 'POST', (db.licenses || []).map(cloudLicenseRow))); const ceRows = (db.nbcrnaCE || []).map(x => cloudCeRow(x, 'nbcrna')).concat((db.aanaCE || []).map(x => cloudCeRow(x, 'aana'))); if (ceRows.length) rows.push(sbReq('/rest/v1/ce_records', 'POST', ceRows)); await Promise.all(rows); await cloudUpsertPortals(); cloudActive = true; cloudPending = null; cloudOffline = false; cloudError = ''; cloudLastSync = cloudNow(); cloudPersistSession(); render(); alert('On-device credential records uploaded to your cloud account.'); } catch (e) { cloudOffline = true; cloudError = e.message; render(); alert('Upload failed: ' + e.message); } }
function cloudApplyData(data) { const prevN = db.nbcrna || {}, prevA = db.aana || {}; if (data.nbcrna) { const r = data.nbcrna; db.nbcrna = { status: r.certification_status || '', number: r.certification_number || '', periodStart: r.period_start || '', periodEnd: r.period_end || '', renewalDeadline: r.renewal_deadline || r.period_end || '', classA: r.class_a_credits === null || r.class_a_credits === undefined ? '' : String(r.class_a_credits), classB: r.class_b_credits === null || r.class_b_credits === undefined ? '' : String(r.class_b_credits), macEd: r.mac_ed_credits === null || r.mac_ed_credits === undefined ? '' : String(r.mac_ed_credits), macDev: r.mac_dev_credits === null || r.mac_dev_credits === undefined ? '' : String(r.mac_dev_credits), macEdRequired: r.mac_ed_required || 60, macDevRequired: r.mac_dev_required || 40, docNote: prevN.docNote || '', ceNote: prevN.ceNote || '', reminders: prevN.reminders || '90,60,30,7' }; cloudSyncTimes.nbcrna = r.last_synced_at || ''; } const licRem = {}; (db.licenses || []).forEach(x => { licRem[x.id] = x.reminders; }); db.licenses = (data.licenses || []).map(r => ({ id: r.id, state: r.state, type: r.license_type, number: r.license_number || '', issue: r.issue_date || '', expiry: r.expiration_date || '', portal: r.board_portal_url || '', note: r.notes || '', reminders: licRem[r.id] || '90,60,30,7' })); if ((data.licenses || []).length) cloudSyncTimes.licenses = (data.licenses || []).map(r => r.last_synced_at || '').sort().pop(); if (data.aana) { const r = data.aana; db.aana = { status: r.membership_status || '', number: r.membership_number || '', expiration: r.expiration || '', docNote: prevA.docNote || '', ceNote: prevA.ceNote || '', reminders: prevA.reminders || '90,60,30,7' }; cloudSyncTimes.aana = r.last_synced_at || ''; } db.nbcrnaCE = (data.ce || []).filter(r => r.source === 'nbcrna').map(r => ({ id: r.id, title: r.title || '', date: r.completed_date || '', credits: r.credits === null || r.credits === undefined ? '' : String(r.credits), class: r.credit_class || 'Class A' })); db.aanaCE = (data.ce || []).filter(r => r.source === 'aana').map(r => ({ id: r.id, title: r.title || '', date: r.completed_date || '', credits: r.credits === null || r.credits === undefined ? '' : String(r.credits), note: '' })); cloudActive = true; cloudPending = null; cloudOffline = false; cloudError = ''; cloudLastSync = cloudNow(); cloudPersistSession(); persist(); }
async function cloudLoadIntoLocal() { if (!cloudSession) return; try { const data = await cloudFetchAll(); cloudApplyData(data); render(); alert('Cloud credential records loaded onto this device.'); } catch (e) { cloudOffline = true; cloudError = e.message; render(); alert('Sync failed: ' + e.message); } }
async function cloudAfterSignIn() { try { const data = await cloudFetchAll(); const counts = cloudCountsOf(data); if (cloudActive) { cloudApplyData(data); } else { cloudPending = { counts: counts, hasLocal: cloudLocalHasRecords() }; } render(); setTab('Account'); } catch (e) { cloudOffline = true; cloudError = e.message; cloudPending = { counts: null, hasLocal: cloudLocalHasRecords() }; render(); setTab('Account'); } }
async function submitCloudAuth(e) { e.preventDefault(); const fd = new FormData(e.currentTarget); const email = String(fd.get('email') || '').trim(), password = String(fd.get('password') || ''); if (!email || !password) return alert('Enter an email and password.'); try { const data = await sbAuthReq('/auth/v1/token?grant_type=password', { email: email, password: password }); if (!cloudStoreSession(data)) throw new Error('Sign-in succeeded but no session was returned. If email confirmation is required, confirm from your inbox, then sign in again.'); await cloudAfterSignIn(); } catch (err) { alert('Sign-in failed: ' + err.message); } }
async function cloudSignUp(email, password) { try { const data = await sbAuthReq('/auth/v1/signup', { email: email, password: password }); if (!cloudStoreSession(data)) { alert('Account created. If Supabase requires email confirmation, confirm from your inbox, then sign in with the form above.'); return; } await cloudAfterSignIn(); } catch (err) { alert('Sign-up failed: ' + err.message); } }
async function cloudSignOut() { try { if (cloudSession) await fetch(SUPABASE_CFG.url + '/auth/v1/logout', { method: 'POST', headers: { apikey: SUPABASE_CFG.anonKey, Authorization: 'Bearer ' + cloudSession.access_token } }); } catch (e) {} cloudSession = null; cloudActive = false; cloudPending = null; cloudOffline = false; cloudError = ''; cloudPersistSession(); render(); }
function cloudSaveKind(kind, savedId) { if (!cloudSyncEnabled()) return; (async () => { try { if (kind === 'nbcrna') { if (cloudLocalHasNbcrna()) { await sbReq('/rest/v1/nbcrna_profiles', 'POST', cloudNbcrnaRow()); await cloudUpsertPortals(); } } else if (kind === 'aana') { if (cloudLocalHasAana()) { await sbReq('/rest/v1/aana_memberships', 'POST', cloudAanaRow()); await cloudUpsertPortals(); } } else if (kind === 'licenses') { const rec = (db.licenses || []).find(x => x.id === savedId); if (rec) { await sbReq('/rest/v1/licenses', 'POST', cloudLicenseRow(rec)); await cloudUpsertPortals(); } } else if (kind === 'nbcrnaCE') { const rec = (db.nbcrnaCE || []).find(x => x.id === savedId); if (rec) await sbReq('/rest/v1/ce_records', 'POST', cloudCeRow(rec, 'nbcrna')); } else if (kind === 'aanaCE') { const rec = (db.aanaCE || []).find(x => x.id === savedId); if (rec) await sbReq('/rest/v1/ce_records', 'POST', cloudCeRow(rec, 'aana')); } cloudOffline = false; cloudError = ''; cloudLastSync = cloudNow(); cloudPersistSession(); } catch (e) { cloudOffline = true; cloudError = e.message; } })(); }
function cloudDeleteKind(kind, entryId) { if (!cloudSyncEnabled()) return; (async () => { try { const table = kind === 'licenses' ? 'licenses' : 'ce_records'; await sbReq('/rest/v1/' + table + '?id=eq.' + encodeURIComponent(entryId), 'DELETE'); } catch (e) { cloudOffline = true; cloudError = e.message; } })(); }
function cloudPortalState(key) { if (!SUPABASE_CONFIGURED) return { label: 'Not connected', detail: 'Supabase not configured — paste the publishable key (see the Account tab)' }; if (!cloudSession) return { label: 'Not connected', detail: 'Sign in on the Account tab to sync records to your account' }; if (cloudPending || !cloudActive) return { label: 'Not connected', detail: 'Signed in — choose upload or load on the Account tab first' }; if (cloudOffline) return { label: 'Signed in (offline)', detail: 'Showing the on-device copy; the last sync attempt failed' + (cloudError ? ' (' + cloudError + ')' : '') }; const has = key === 'nbcrna' ? cloudLocalHasNbcrna() : key === 'aana' ? cloudLocalHasAana() : (db.licenses || []).length > 0; const when = cloudSyncTimes[key]; if (has) return { label: 'Connected', detail: 'Account synced' + (when ? ' · last synced ' + cloudFmtWhen(when) : '') + ' — portal pull not yet available; records are user-entered, not verified' }; return { label: 'Connected', detail: 'No records yet — add one in the manual fallback below; portal pull not yet available' }; }
function cloudCountsLine(c) { if (!c) return 'unknown'; return 'NBCRNA: ' + c.nbcrna + ' · AANA: ' + c.aana + ' · Licenses: ' + c.licenses + ' · CE records: ' + c.ce; }
function accountPage() {
  if (!SUPABASE_CONFIGURED) return `<section class="panel"><h2>Account — Supabase not configured</h2><p><strong>Sign-in and cloud sync are not available yet.</strong> The app is working on-device only, exactly as before.</p><p class="muted">To enable it, the owner pastes the project's publishable (anon) key into <code>supabase-config.js</code> (replacing <code>PASTE_PUBLISHABLE_KEY_HERE</code>) and redeploys. Find it in the Supabase dashboard: Project Settings → API → Publishable key, for project <code>xgoghgihfhtnyevgapyp</code> (<code>https://xgoghgihfhtnyevgapyp.supabase.com</code>).</p><p class="muted">The publishable key is a public client key and is safe to embed. Never paste the secret key or service-role key into this repo or any client file — those bypass Row Level Security and belong server-side only.</p><p class="muted">Until the key is filled in, nothing here fails silently: this page, the header, and the Credentials cards all say "not configured".</p></section>`;
  if (!cloudSession) return `<section class="panel"><h2>Account — sign in to sync credentials</h2><p class="muted">Signing in syncs NBCRNA, AANA, license, and CE records (and portal-connection status) between this device and your Supabase account. Shifts, facilities, mileage, and PTO stay on this device in this release. Live NBCRNA / AANA / state portal pulls are not built yet — synced records are still user-entered, not verified, and no portal passwords are ever stored.</p><form id="cloudAuthForm"><div class="form-grid">${field('email', 'Email', 'email', '', 'required autocomplete="email"')}${field('password', 'Password', 'password', '', 'required autocomplete="current-password"')}</div>${formEnd('Sign in')}</form><div class="toolbar"><button type="button" class="secondary" data-action="cloud-signup">Create account</button></div><p class="muted">Creating an account uses Supabase Auth (email + password). If Supabase requires email confirmation, confirm from your inbox, then sign in.</p></section>`;
  if (cloudPending) { const c = cloudPending.counts; return `<section class="panel"><h2>Account — choose how to sync</h2><p><strong>Signed in as ${escapeHTML(cloudSession.email || '')}.</strong> Before anything syncs, choose one direction. Nothing has been overwritten.</p><p class="muted">Cloud records: ${escapeHTML(cloudCountsLine(c))}</p><p class="muted">On-device records: ${escapeHTML(cloudCountsLine(cloudLocalCounts()))}</p><div class="toolbar"><button data-action="cloud-upload">Upload my on-device records to my account</button><button class="secondary" data-action="cloud-load">Load cloud records onto this device</button></div><p class="muted">Upload overwrites the cloud credential records with the ones on this device. Load replaces the credential records on this device with the cloud ones. Either way, shifts, facilities, mileage, and PTO are untouched.</p><div class="toolbar"><button type="button" class="secondary tiny" data-action="cloud-keep-local">Decide later (keep working on-device for now)</button><button type="button" class="secondary tiny" data-action="cloud-signout">Sign out</button></div></section>`; }
  const lc = cloudLocalCounts(); return `<section class="panel"><h2>Account</h2><p><strong>Signed in as ${escapeHTML(cloudSession.email || '')}.</strong> Mode: <strong>${escapeHTML(cloudHeaderLabel())}</strong></p><p class="muted">On-device credential records: ${escapeHTML(cloudCountsLine(lc))}${cloudLastSync ? ' · Last sync: ' + escapeHTML(cloudFmtWhen(cloudLastSync)) : ''}</p>${cloudError ? `<p class="muted">Last sync problem: ${escapeHTML(cloudError)}</p>` : ''}<p class="muted">Credential edits here save to your cloud account automatically while signed in. Shifts, facilities, mileage, and PTO stay on this device. Live portal pulls are not built yet — records are user-entered, not verified.</p><div class="toolbar"><button data-action="cloud-sync">Sync now (download cloud records)</button><button class="secondary" data-action="cloud-upload">Upload my on-device records</button><button class="secondary" data-action="cloud-signout">Sign out</button></div><p class="muted">Sync now replaces the credential records on this device with the cloud ones. Upload overwrites the cloud credential records with the ones on this device. Both ask for confirmation first.</p></section>`;
}
async function cloudInit() { if (!SUPABASE_CONFIGURED || !cloudSession) return; try { await cloudEnsureToken(); } catch (e) { cloudSession = null; cloudActive = false; cloudPending = null; cloudPersistSession(); render(); return; } if (cloudActive) { try { const data = await cloudFetchAll(); cloudApplyData(data); render(); } catch (e) { cloudOffline = true; cloudError = e.message; render(); } } else { try { const data = await cloudFetchAll(); cloudPending = { counts: cloudCountsOf(data), hasLocal: cloudLocalHasRecords() }; render(); } catch (e) { cloudPending = { counts: null, hasLocal: cloudLocalHasRecords() }; render(); } } }

render();cloudInit();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
